#define UNICODE
#define NOMINMAX
#include <windows.h>
#include <iostream>
#include <fstream>
#include <vector>
bool snap(HWND w,const wchar_t*name){RECT r;GetClientRect(w,&r);int width=r.right,height=r.bottom;HDC dc=GetDC(w),mem=CreateCompatibleDC(dc);HBITMAP bm=CreateCompatibleBitmap(dc,width,height);auto old=SelectObject(mem,bm);BitBlt(mem,0,0,width,height,dc,0,0,SRCCOPY);BITMAPINFO bi{};bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=width;bi.bmiHeader.biHeight=-height;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;bi.bmiHeader.biCompression=BI_RGB;std::vector<char>bytes(width*height*4);GetDIBits(mem,bm,0,height,bytes.data(),&bi,DIB_RGB_COLORS);BITMAPFILEHEADER fh{};fh.bfType=0x4D42;fh.bfOffBits=sizeof(fh)+sizeof(BITMAPINFOHEADER);fh.bfSize=fh.bfOffBits+(DWORD)bytes.size();HANDLE f=CreateFileW(name,GENERIC_WRITE,0,nullptr,CREATE_ALWAYS,0,nullptr);DWORD n;WriteFile(f,&fh,sizeof(fh),&n,nullptr);WriteFile(f,&bi.bmiHeader,sizeof(BITMAPINFOHEADER),&n,nullptr);WriteFile(f,bytes.data(),(DWORD)bytes.size(),&n,nullptr);CloseHandle(f);SelectObject(mem,old);DeleteObject(bm);DeleteDC(mem);ReleaseDC(w,dc);return true;}
int main(){HWND h=nullptr;for(int i=0;i<100&&!h;i++){h=FindWindowW(L"UsageWidget",nullptr);Sleep(100);}if(!h){std::cerr<<"FAIL startup\n";return 1;}Sleep(3000);snap(h,L"light.bmp");SendMessageW(h,WM_COMMAND,103,0);Sleep(500);snap(h,L"dark.bmp");SendMessageW(h,WM_COMMAND,108,0);Sleep(500);HWND s=FindWindowW(L"UsageSettings",nullptr);if(!s){std::cerr<<"FAIL settings\n";return 2;}snap(s,L"settings.bmp");HWND host=GetDlgItem(s,300),password=GetDlgItem(s,305);if(host||password){std::cerr<<"FAIL retired controls still present\n";return 3;}float dpi=GetDpiForWindow(s)/96.f;SendMessageW(s,WM_LBUTTONDOWN,0,MAKELPARAM((int)(450*dpi),(int)(238*dpi)));SendMessageW(s,WM_LBUTTONUP,0,MAKELPARAM((int)(450*dpi),(int)(238*dpi)));SendMessageW(s,WM_CLOSE,0,0);SetWindowPos(h,nullptr,120,100,500,550,SWP_NOZORDER);RECT r;GetWindowRect(h,&r);if(r.right-r.left!=500){std::cerr<<"FAIL resize\n";return 4;}SendMessageW(h,WM_EXITSIZEMOVE,0,0);SendMessageW(h,WM_COMMAND,115,0);GetWindowRect(h,&r);if(r.bottom-r.top>150){std::cerr<<"FAIL capsule mode\n";return 5;}SendMessageW(h,WM_NCLBUTTONDBLCLK,HTCAPTION,0);SendMessageW(h,WM_COMMAND,100,0);Sleep(500);SendMessageW(h,WM_COMMAND,107,0);std::cout<<"PASS startup, simplified settings, opacity, theme, resize, capsule, double-click, refresh, exit\n";return 0;}
